/**
 * Read a {@link Response} body into a {@link FetchedFile} object.
 * The filename is taken from the first usable source below:
 * - Content-Disposition header filename*
 * - Content-Disposition header filename
 * - Final response URL's last component
 * - Original request URL's last component
 * - Placeholder name `download`
 *
 * @internal
 */
export async function readResponseAsFile(response, requestUrl, onChunk) {
    let buffer;
    // No progress wanted, or no streamable body to report from.
    if (!onChunk || !response.body) {
        buffer = await response.arrayBuffer();
    }
    else {
        const totalHeader = response.headers.get('content-length');
        const parsed = totalHeader == null ? NaN : Number(totalHeader);
        const total = Number.isFinite(parsed) ? parsed : null;
        const reader = response.body.getReader();
        const chunks = [];
        let received = 0;
        onChunk(0, total);
        while (true) {
            const { done, value } = await reader.read();
            if (done)
                break;
            if (value) {
                chunks.push(value);
                received += value.length;
                onChunk(received, total);
            }
        }
        const bytes = new Uint8Array(received);
        let offset = 0;
        for (const chunk of chunks) {
            bytes.set(chunk, offset);
            offset += chunk.length;
        }
        buffer = bytes.buffer;
    }
    return {
        buffer,
        filename: dispositionFilename(response.headers.get('content-disposition')) ??
            urlFilename(response.url) ??
            urlFilename(requestUrl) ??
            'download',
    };
}
/**
 * Extract the final component of a path-like string.
 * Return `undefined` if the input contains ASCII control characters or the
 * extracted name is empty, `.` or `..`.
 */
function safeBasename(value) {
    if (/[\u0000-\u001f\u007f]/u.test(value))
        return undefined;
    const name = value.split(/[\\/]/u).at(-1)?.trim();
    return name && name !== '.' && name !== '..' ? name : undefined;
}
/** Extract a file name from Content-Disposition `filename*` or `filename` parameters. */
function dispositionFilename(header) {
    if (!header)
        return undefined;
    const parameters = new Map();
    // Quoted parameter values may contain semicolons and escaped quotes.
    const parameterName = String.raw `[^=;\s]+`;
    const quotedValue = String.raw `"(?:[^"\\]|\\.)*"`;
    const unquotedValue = String.raw `[^";]*`;
    const parameterPattern = new RegExp(String.raw `;\s*(?<name>${parameterName})\s*=\s*(?<value>${quotedValue}|${unquotedValue})(?=\s*(?:;|$))`, 'gu');
    for (const match of header.matchAll(parameterPattern)) {
        const key = match.groups.name.toLowerCase();
        let value = match.groups.value.trim();
        // Preserve backslashes other than escaped quotes/backslashes.
        if (value.startsWith('"'))
            value = value.slice(1, -1).replace(/\\(["\\])/gu, '$1');
        if (!parameters.has(key))
            parameters.set(key, value);
    }
    const extended = parameters.get('filename*');
    if (extended) {
        // filename* is formatted like this: charset'language'value, e.g. UTF-8'en'caf%C3%A9.nii.
        // Support UTF-8 only and skip the optional language field.
        const match = /^UTF-8'[^']*'(.*)$/iu.exec(extended);
        if (match) {
            try {
                const name = safeBasename(decodeURIComponent(match[1]));
                if (name)
                    return name;
            }
            catch { }
        }
    }
    // Unlike filename*, filename values are not percent-encoded.
    return safeBasename(parameters.get('filename') ?? '');
}
/** Extract a decoded final URL path component */
function urlFilename(url) {
    if (!url)
        return undefined;
    try {
        const pathname = new URL(url, window.location.href).pathname;
        return safeBasename(decodeURIComponent(pathname.slice(pathname.lastIndexOf('/') + 1)));
    }
    catch {
        return undefined;
    }
}
